#!/usr/bin/env bash
# Install the built wheel in a clean environment and use it, as a user would (#71).
#
#   uv build && ./scripts/package_smoke.sh
#
# Checks that both commands run, that the templates ship in the wheel, and that a
# server generated by the installed package compiles. Needs no network beyond
# installing the wheel's dependencies.
set -euo pipefail

root="$(cd "$(dirname "$0")/.." && pwd)"
wheel="$(ls "$root"/dist/docs2mcp_cli-*.whl | tail -n 1)"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT

uv venv --quiet --python 3.14 "$work/venv"
VIRTUAL_ENV="$work/venv" uv pip install --quiet "$wheel"
bin="$work/venv/bin"

"$bin/docs2mcp" --version
"$bin/docs2mcp-cli" --version

design="$root/evals/agent/conditions/openapi/frankfurter"
cd "$work"  # run outside the repo, so nothing is imported from src/
"$bin/docs2mcp" generate "$design/tools.json" --spec "$design/spec.json" --out "$work/server"
"$bin/python" -m py_compile "$work/server/server.py"
grep -q "Generated by docs2mcp" "$work/server/server.py"
echo "package smoke test passed: $(basename "$wheel")"
